const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const donnerPass = ee.Geometry.Point([-120.3, 39.3]);
  const startDate = '2022-01-01';
  const endDate = '2022-04-30';

  console.log("Analyzing SWE at Donner Pass (Jan-Apr 2022)");

  // 2. Data Acquisition - ERA5-Land has snow_depth_water_equivalent
  const era5 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
    .filterDate(startDate, endDate)
    .filterBounds(donnerPass)
    .select('snow_depth_water_equivalent'); // in meters

  const imageCount = era5.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No ERA5-Land data available for this period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get maximum SWE over the period
  const maxSWE = era5.max();

  // 4. Calculate SWE at Donner Pass
  const sweResult = maxSWE.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: donnerPass,
    scale: 11132,
    maxPixels: 1e9
  }).getInfo();

  const sweMeters = sweResult.snow_depth_water_equivalent;

  // 5. Validation & Conversion
  if (sweMeters === null || sweMeters === undefined || isNaN(sweMeters)) {
    console.log("SWE calculation failed - invalid result");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert meters to inches (1 meter = 39.3701 inches)
  const sweInches = sweMeters * 39.3701;

  console.log(`Max SWE (Jan-Apr 2022): ${sweMeters.toFixed(3)} meters`);
  console.log(`Max SWE (Jan-Apr 2022): ${sweInches.toFixed(2)} inches`);
  console.log(`Threshold: 40 inches`);

  // 6. Final Answer
  if (sweInches > 40) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
